static void run(final FastScanner scanner, final PrintWriter out) {
    int N = scanner.nextInt();
    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            for (int k = 0; k <= N - i - j; k++) {
                out.println(i + " " + j + " " + k);
            }
        }
    }
}
